import '@emotion/react';

declare module '@emotion/react' {
  export interface Theme {
    colors: {
      background: string;
      text: string;
      primary: string;
      secondary: string;
      accent: string;
      gradient: string;
    }
  }
}

export const theme = {
  light: {
    colors: {
      background: '#ffffff',
      text: '#2d3436',
      primary: '#0984e3',
      secondary: '#00b894',
      accent: '#6c5ce7',
      gradient: 'linear-gradient(135deg, #0984e3 0%, #6c5ce7 100%)'
    }
  },
  dark: {
    colors: {
      background: '#0a0a0a',
      text: '#f5f6fa',
      primary: '#00a8ff',
      secondary: '#00d2d3',
      accent: '#9c88ff',
      gradient: 'linear-gradient(135deg, #0a0a0a 0%, #1a1a1a 100%)'
    }
  }
};

export const defaultTheme = theme.dark;
